CREATE OR REPLACE FUNCTION public.admin_set_role(_target_user uuid,_make_admin boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.admin_set_user_role(_target_user,CASE WHEN _make_admin THEN 'admin'::public.app_role ELSE 'user'::public.app_role END); END $$;
REVOKE ALL ON FUNCTION public.admin_set_role(uuid,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.admin_set_role(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.metrics_drilldown(_metric text,_scope jsonb DEFAULT '{}',_limit integer DEFAULT 25,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE snap jsonb;s jsonb;rows jsonb;total integer;BEGIN snap:=public.metrics_snapshot(_scope);s:=snap->'scope';IF snap->>'audience'='investor' THEN RAISE EXCEPTION 'المستثمر يعرض الملخصات المجمعة فقط' USING ERRCODE='42501';END IF;IF _metric IN('units','available','leased','on_hold','pending_contract','maintenance','draft','published','review') THEN IF snap->>'audience'='accountant' OR (snap->>'audience'='control' AND _metric<>'maintenance') THEN RAISE EXCEPTION 'غير مسموح بعرض هذه القائمة';END IF;WITH filtered AS(SELECT * FROM public.metrics_unit_scope u WHERE public.metrics_scope_match(u,s) AND CASE WHEN _metric='units' THEN true WHEN _metric IN('draft','published') THEN publish_state=_metric WHEN _metric='review' THEN leasing_status IS NULL ELSE leasing_status::text=_metric END),paged AS(SELECT * FROM filtered ORDER BY building_number,unit_number,id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM paged p),'[]'),(SELECT count(*) FROM filtered) INTO rows,total;ELSIF _metric IN('due','overdue','installments','collected','receipts_to_verify') THEN IF snap->'finance' IS NULL THEN RAISE EXCEPTION 'غير مسموح بعرض المالية';END IF;IF _metric IN('collected','receipts_to_verify') THEN WITH factors AS(SELECT cu.contract_id,sum(cu.annual_rent_excl_vat)/nullif(c.annual_rent_excl_vat,0) AS factor FROM public.contract_units cu JOIN public.contracts c ON c.id=cu.contract_id JOIN public.metrics_unit_scope u ON u.id=cu.unit_id WHERE public.metrics_scope_match(u,s) GROUP BY cu.contract_id,c.annual_rent_excl_vat),filtered AS(SELECT r.id,r.receipt_no,r.paid_at,r.status,r.amount_excl_vat*coalesce(f.factor,1) AS amount_excl_vat,r.vat_amount*coalesce(f.factor,1) AS vat_amount FROM public.receipt_cash_read r LEFT JOIN factors f ON f.contract_id=r.contract_id WHERE r.reverses_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.receipts rev WHERE rev.reverses_id=r.id) AND ((f.factor IS NOT NULL) OR (r.contract_id IS NULL AND s->>'building' IS NULL AND s->>'phase' IS NULL AND s->>'activity' IS NULL AND s->>'unit_type' IS NULL)) AND CASE WHEN _metric='receipts_to_verify' THEN r.status='recorded' ELSE r.status='verified' AND r.paid_at>=((s->>'from')::date::timestamp AT TIME ZONE 'Asia/Riyadh') AND r.paid_at<(((s->>'to')::date+1)::timestamp AT TIME ZONE 'Asia/Riyadh') END),paged AS(SELECT * FROM filtered ORDER BY paid_at DESC,id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM paged p),'[]'),(SELECT count(*) FROM filtered) INTO rows,total;ELSE WITH factors AS(SELECT cu.contract_id,sum(cu.annual_rent_excl_vat)/nullif(c.annual_rent_excl_vat,0) AS factor FROM public.contract_units cu JOIN public.contracts c ON c.id=cu.contract_id JOIN public.metrics_unit_scope u ON u.id=cu.unit_id WHERE public.metrics_scope_match(u,s) GROUP BY cu.contract_id,c.annual_rent_excl_vat),filtered AS(SELECT i.id,i.contract_id,i.sequence_no,i.due_date,round(i.remaining_excl*f.factor,2) AS amount_excl_vat,round(i.remaining_vat*f.factor,2) AS vat_amount FROM public.metrics_installment_balances i JOIN factors f ON f.contract_id=i.contract_id WHERE i.due_date BETWEEN (s->>'from')::date AND (s->>'to')::date AND CASE WHEN _metric='installments' THEN true ELSE i.remaining_excl+i.remaining_vat>0 AND i.due_date<(now() AT TIME ZONE 'Asia/Riyadh')::date AND (_metric='due' OR public.metrics_is_overdue(i.due_date,(now() AT TIME ZONE 'Asia/Riyadh')::date,(snap->'finance'->>'grace_days')::integer)) END),paged AS(SELECT * FROM filtered ORDER BY due_date,id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM paged p),'[]'),(SELECT count(*) FROM filtered) INTO rows,total;END IF;ELSIF _metric='holds' OR _metric LIKE 'stage:%' THEN IF snap->'pipeline' IS NULL THEN RAISE EXCEPTION 'غير مسموح بعرض الفرص';END IF;IF _metric='holds' THEN WITH filtered AS(SELECT b.id,b.offer_number,b.expires_at FROM public.bookings b WHERE b.status='pending' AND b.archived_at IS NULL AND b.expires_at>=now() AND b.expires_at<now()+interval '24 hours' AND EXISTS(SELECT 1 FROM public.booking_units bu JOIN public.metrics_unit_scope u ON u.id=bu.unit_id WHERE bu.booking_id=b.id AND u.leasing_status='on_hold' AND public.metrics_scope_match(u,s))),paged AS(SELECT * FROM filtered ORDER BY expires_at,id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM paged p),'[]'),(SELECT count(*) FROM filtered) INTO rows,total;ELSE WITH filtered AS(SELECT o.id,o.stage,o.next_action_at FROM public.opportunities o WHERE o.outcome IS NULL AND o.stage::text=substring(_metric from 7) AND public.metrics_opportunity_matches(o.id,s)),paged AS(SELECT * FROM filtered ORDER BY next_action_at,id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM paged p),'[]'),(SELECT count(*) FROM filtered) INTO rows,total;END IF;ELSE RAISE EXCEPTION 'قائمة مؤشر غير متاحة';END IF;RETURN jsonb_build_object('rows',rows,'count',total,'as_of',snap->'as_of','scope',s);END $$;
REVOKE ALL ON FUNCTION public.metrics_drilldown(text,jsonb,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.metrics_drilldown(text,jsonb,integer,integer) TO authenticated;
SELECT to_regprocedure('public.metrics_drilldown(text,jsonb,integer,integer)') IS NOT NULL AS drilldown_ready,has_table_privilege('authenticated','public.metrics_receipt_scope','SELECT') AS raw_metric_access_must_be_false;